* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #2b2b2b;
  color: #f0f0f0;
  font-family: 'Courier New', monospace;
}

.pixel-panel {
  width: min(90%, 520px);
  background: #1a1a1a;
  border: 4px solid #fff;
  box-shadow: 8px 8px 0 #000;
  padding: 20px;
  image-rendering: pixelated;
}

h1 {
  margin: 0 0 16px;
  text-align: center;
  text-shadow: 3px 3px 0 #000;
}

.controls {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 16px;
}

.controls label {
  font-weight: bold;
}

#todo-input {
  flex: 1;
  background: #000;
  border: 4px solid #fff;
  color: #0f0;
  padding: 8px;
  font: inherit;
  outline: none;
  box-shadow: inset 3px 3px 0 #333;
}

#todo-add {
  background: #ff0055;
  border: 4px solid #fff;
  color: #fff;
  padding: 8px 12px;
  font: inherit;
  font-weight: bold;
  cursor: pointer;
  box-shadow: 4px 4px 0 #000;
}

#todo-add:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 #000;
}

.stats {
  display: flex;
  justify-content: space-between;
  margin-bottom: 12px;
  padding: 8px;
  border: 4px solid #fff;
  background: #000;
}

#todo-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

#todo-list li {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
  padding: 8px;
  background: #000;
  border: 4px solid #fff;
  box-shadow: 4px 4px 0 #000;
}

#todo-list input[type='checkbox'] {
  width: 20px;
  height: 20px;
  accent-color: #0f0;
  cursor: pointer;
}

.task-text {
  flex: 1;
  cursor: pointer;
  overflow-wrap: anywhere;
}

#todo-list li.completed .task-text {
  text-decoration: line-through;
  color: #777;
}

#todo-list button {
  background: #ff0055;
  border: 4px solid #fff;
  color: #fff;
  padding: 4px 8px;
  font: inherit;
  font-weight: bold;
  cursor: pointer;
  box-shadow: 2px 2px 0 #000;
}

#todo-list button:active {
  transform: translate(1px, 1px);
  box-shadow: 1px 1px 0 #000;
}

(() => {
  const input = document.getElementById('todo-input');
  const addBtn = document.getElementById('todo-add');
  const list = document.getElementById('todo-list');
  const totalEl = document.getElementById('todo-total');
  const remainingEl = document.getElementById('remaining');
  const tasks = [];
  let nextId = 1;

  const updateCounts = () => {
    totalEl.textContent = String(tasks.length);
    remainingEl.textContent = String(tasks.filter(task => !task.completed).length);
  };

  const renderTask = (task) => {
    const li = document.createElement('li');
    li.dataset.id = String(task.id);
    if (task.completed) li.classList.add('completed');

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = `todo-check-${task.id}`;
    checkbox.checked = task.completed;
    checkbox.addEventListener('change', () => {
      task.completed = checkbox.checked;
      li.classList.toggle('completed', task.completed);
      updateCounts();
    });

    const label = document.createElement('label');
    label.htmlFor = checkbox.id;
    label.className = 'task-text';
    const span = document.createElement('span');
    span.id = `todo-text-${task.id}`;
    span.textContent = task.text;
    label.appendChild(span);

    const deleteBtn = document.createElement('button');
    deleteBtn.type = 'button';
    deleteBtn.id = `todo-delete-${task.id}`;
    deleteBtn.textContent = 'Delete';
    deleteBtn.setAttribute('aria-label', `Delete ${task.text}`);
    deleteBtn.addEventListener('click', () => {
      const index = tasks.findIndex(t => t.id === task.id);
      if (index !== -1) tasks.splice(index, 1);
      li.remove();
      updateCounts();
    });

    li.append(checkbox, label, deleteBtn);
    list.appendChild(li);
  };

  const addTask = () => {
    const text = input.value.trim();
    if (!text) return;
    const task = { id: nextId, text, completed: false };
    tasks.push(task);
    nextId += 1;
    renderTask(task);
    input.value = '';
    updateCounts();
    input.focus();
  };

  addBtn.addEventListener('click', addTask);
  input.addEventListener('keydown', (event) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      addTask();
    }
  });

  updateCounts();
})();
